INSERT INTO promotions (id,client_type,number_code,name,description,start_date,end_date,min_years,allowed_conditions,restricted_conditions,legal_obligations,is_new_client,is_retention_only,discount_percent,duration_months,discount_schedule) VALUES
(1,'b2c','№3','Скидка на доп. ТВ-приставку «Все включено»','Подключение дополнительных приёмников на тариф «ТВ: все включено» со скидкой от базовой стоимости. Установочная плата не взимается.','2026-01-01','2026-12-31',0,'Новые и существующие абоненты телевидения и пакетов с интерактивным телевидением.','Не действует для пакетов Альфа 35 и Альфа 100. Однократно на адрес.',NULL,NULL,0,55,9,NULL),
(2,'b2c','№5','Скидка на пакет «Премиум HD»','Скидка на пакет «Премиум HD».','2026-01-01','2026-12-31',0,'Новые и существующие абоненты.','Однократно для одного абонента.',NULL,NULL,0,90,1,NULL),
(3,'b2c','№6','Скидка на пакет «Премиум»','Скидка на абонентскую плату пакета «Премиум».','2026-01-01','2026-12-31',0,'Новые и существующие абоненты.','Абонент не пользовался пакетом Премиум с 15.10.2023.',NULL,NULL,0,85,2,NULL),
(4,'b2c','№8','Программа лояльности 25%','Скидка на тарифы и пакеты услуг при сохранении договора.','2026-01-01','2026-12-31',0,'Абоненты, обратившиеся в сервисный центр для расторжения договора.','Исключены архивные тарифы и отдельные тарифы линейки Альфа.', 'Анкета и предварительное уведомление за 30 дней.',0,1,25,9,NULL),
(5,'b2c','№9','Программа лояльности 35%','Скидка на абонентскую плату пакета услуг при сохранении действующего договора.','2026-02-12','2026-12-31',2,'Существующие физические лица с пакетами Альфа или Бета.','Для отказавшихся от программы лояльности 25%.',NULL,0,1,35,9,NULL),
(6,'b2c','№10','Программа лояльности 45%','Скидка на абонентскую плату пакета услуг при сохранении договора.','2026-02-12','2026-12-31',4,'Существующие физические лица с пакетами Альфа или Бета.','Для отказавшихся от программ 25% и 35%.','Пользование услугой не менее 13 месяцев с даты активации.',0,1,45,9,NULL),
(7,'b2c','№11','Скидка на пакеты 18 месяцев','Скидка на абонентскую плату выбранных пакетов услуг.','2026-01-01','2026-12-31',0,'Абоненты подходящих пакетов.','Однократно на адрес; только с финансовым плюсом.',NULL,NULL,0,45,18,'1–9 мес.: 45%; 10–18 мес.: 20%'),
(8,'b2c','№14','Скидка на пакет 25%','Скидка для новых абонентов при подключении пакетов Альфа и Бета.','2026-01-01','2026-12-31',0,'Новые физические лица.','Однократно на адрес; учитываются расторгнутые за последние 30 дней услуги.',NULL,1,0,25,9,NULL),
(9,'b2c','№16','Скидка на Альфа Лайт 60%','Скидка на абонентскую плату пакета «Альфа Лайт».','2026-01-01','2026-12-31',0,'Новые физические лица.','Однократно; за 30 дней по адресу не должно быть услуг.',NULL,1,0,60,9,NULL),
(10,'b2c','№20','Скидка 35/15 на пакеты 18 месяцев','Скидка на абонентскую плату пакетов Альфа.','2026-02-12','2026-12-31',0,'Физические лица, подключающиеся к подходящим пакетам.','Однократно на адрес; только с финансовым плюсом.',NULL,NULL,0,35,18,'1–9 мес.: 35%; 10–18 мес.: 15%'),
(11,'b2c','№22','Скидка на Видеоконтроль Дом 85% на 2 месяца','Скидка на подключение и абонентскую плату услуги видеоконтроля.','2026-01-01','2026-12-31',0,'Новые физические лица.','Однократно на адрес; не действует на камеры, добавленные позднее.','Пользование набором услуги не менее 5 месяцев.',1,0,85,2,'Подключение: 90%; абонентская плата: 85% на 2 мес.'),
(12,'b2c','№25','Скидка на настройку роутера','Настройка роутера при покупке в рассрочку выполняется без оплаты.','2026-01-01','2026-12-31',0,'Абонент, приобретающий роутер в рассрочку.','Настройка по акции выполняется один раз.',NULL,0,0,NULL,NULL,NULL),
(13,'b2b','№1','Бесплатное подключение автоинформатора','Скидка на пользование блоком автоинформатора и бесплатное подключение к абонентской линии.','2026-01-01','2026-12-31',0,'Юридические лица и ИП, чей номер изменяется при модернизации сети.',NULL,NULL,0,0,90,1,NULL),
(14,'b2b','№2','Скидка 45% 5 месяцев','Скидка при подключении или переключении на бизнес-пакеты.','2026-01-01','2026-12-31',0,'Юридические лица.','Каждый телефонный номер участвует один раз в календарном году.',NULL,NULL,0,45,5,NULL),
(15,'b2b','№6','Предоставление в пользование сети Wi‑Fi','Скидка при подключении сети Wi‑Fi.','2026-01-01','2026-12-31',0,'Новые заказчики с 15 и более точками доступа; также существующие при расторжении договора.','Для существующих заказчиков — при более дешёвом предложении конкурента.',NULL,NULL,0,30,NULL,'Новые заказчики: 30% на 9 мес.; существующие: 30% на 5 мес.'),
(16,'b2b','№7','Программа лояльности 45% для ОАТС','Скидка на абонентскую плату по базовым тарифам услуги «Облачная АТС».','2026-01-01','2026-12-31',0,'Существующие абоненты при обращении за расторжением договора.','Не применяется для новых абонентов.',NULL,0,1,45,2,NULL),
(17,'b2b','№8','Программа лояльности 12% для Видеоконтроля','Скидка на абонентскую плату услуги «Видеоконтроль бизнес».','2026-02-14','2026-12-31',0,'Существующие юридические лица с 8 и более камерами, сохраняющие договор.','Не применяется к организациям, финансируемым из бюджета.',NULL,0,1,12,9,NULL);
